import{_ as a,o as s,c as t,a2 as e}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"GitHub 入门指南：从注册到使用","description":"详细介绍 GitHub 的注册、使用方法，以及国内访问加速方案","frontmatter":{"title":"GitHub 入门指南：从注册到使用","date":"2026-06-09T00:00:00.000Z","description":"详细介绍 GitHub 的注册、使用方法，以及国内访问加速方案","tags":["GitHub","工具","教程"],"cover":"https://images.unsplash.com/photo-1618401471353-b98afee0b2b5?w=800&h=400&fit=crop"},"headers":[],"relativePath":"posts/github-guide.md","filePath":"posts/github-guide.md"}'),l={name:"posts/github-guide.md"};function n(h,i,r,o,p,g){return s(),t("div",null,[...i[0]||(i[0]=[e(`<h1 id="github-入门指南-从注册到使用" tabindex="-1">GitHub 入门指南：从注册到使用 <a class="header-anchor" href="#github-入门指南-从注册到使用" aria-label="Permalink to &quot;GitHub 入门指南：从注册到使用&quot;">​</a></h1><h2 id="什么是-github" tabindex="-1">什么是 GitHub？ <a class="header-anchor" href="#什么是-github" aria-label="Permalink to &quot;什么是 GitHub？&quot;">​</a></h2><p>GitHub 是全球最大的代码托管平台，也是开发者社区。你可以在这里：</p><ul><li>📦 托管自己的代码项目</li><li>🤝 与其他开发者协作</li><li>📚 学习优秀的开源项目</li><li>🚀 部署静态网站（GitHub Pages）</li></ul><p><strong>官网地址</strong>：<a href="https://github.com" target="_blank" rel="noreferrer">https://github.com</a></p><hr><h2 id="注册-github-账号" tabindex="-1">注册 GitHub 账号 <a class="header-anchor" href="#注册-github-账号" aria-label="Permalink to &quot;注册 GitHub 账号&quot;">​</a></h2><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>访问 <a href="https://github.com" target="_blank" rel="noreferrer">https://github.com</a></li><li>点击 <strong>Sign up</strong> 按钮</li><li>输入邮箱、密码、用户名</li><li>完成邮箱验证</li><li>选择免费计划（Free）</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li><strong>用户名</strong>：选择一个好记的名字，这会成为你的个人主页地址（如 <code>github.com/你的用户名</code>）</li><li><strong>邮箱</strong>：建议使用常用邮箱，方便接收通知</li><li><strong>密码</strong>：使用强密码，建议开启两步验证</li></ul><hr><h2 id="github-基础概念" tabindex="-1">GitHub 基础概念 <a class="header-anchor" href="#github-基础概念" aria-label="Permalink to &quot;GitHub 基础概念&quot;">​</a></h2><h3 id="仓库-repository" tabindex="-1">仓库（Repository） <a class="header-anchor" href="#仓库-repository" aria-label="Permalink to &quot;仓库（Repository）&quot;">​</a></h3><p>仓库是项目的基本单位，包含所有的代码文件和历史记录。</p><ul><li><strong>公开仓库</strong>：所有人可见，适合开源项目</li><li><strong>私有仓库</strong>：只有你和授权的人可见</li></ul><h3 id="分支-branch" tabindex="-1">分支（Branch） <a class="header-anchor" href="#分支-branch" aria-label="Permalink to &quot;分支（Branch）&quot;">​</a></h3><p>分支用于开发新功能或修复 bug，不影响主分支。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 创建新分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-new</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 切换到新分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-new</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或者一步完成</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-new</span></span></code></pre></div><h3 id="提交-commit" tabindex="-1">提交（Commit） <a class="header-anchor" href="#提交-commit" aria-label="Permalink to &quot;提交（Commit）&quot;">​</a></h3><p>提交是代码变更的快照，记录了你做了什么修改。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加文件到暂存区</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 提交变更</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;添加了新功能&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 推送到 GitHub</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><h3 id="拉取请求-pull-request" tabindex="-1">拉取请求（Pull Request） <a class="header-anchor" href="#拉取请求-pull-request" aria-label="Permalink to &quot;拉取请求（Pull Request）&quot;">​</a></h3><p>当你想把代码合并到主分支时，需要创建 Pull Request。</p><hr><h2 id="常用-github-功能" tabindex="-1">常用 GitHub 功能 <a class="header-anchor" href="#常用-github-功能" aria-label="Permalink to &quot;常用 GitHub 功能&quot;">​</a></h2><h3 id="_1-创建仓库" tabindex="-1">1. 创建仓库 <a class="header-anchor" href="#_1-创建仓库" aria-label="Permalink to &quot;1. 创建仓库&quot;">​</a></h3><ol><li>点击右上角 <strong>+</strong> 号</li><li>选择 <strong>New repository</strong></li><li>填写仓库名称和描述</li><li>选择公开或私有</li><li>点击 <strong>Create repository</strong></li></ol><h3 id="_2-上传代码" tabindex="-1">2. 上传代码 <a class="header-anchor" href="#_2-上传代码" aria-label="Permalink to &quot;2. 上传代码&quot;">​</a></h3><p><strong>方式一：网页上传</strong></p><ul><li>在仓库页面点击 <strong>Add file</strong> → <strong>Upload files</strong></li><li>拖拽文件到页面</li><li>点击 <strong>Commit changes</strong></li></ul><p><strong>方式二：Git 命令行</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/用户名/仓库名.git</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 进入仓库目录</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 仓库名</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 添加文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;提交信息&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 推送</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span></code></pre></div><h3 id="_3-github-pages" tabindex="-1">3. GitHub Pages <a class="header-anchor" href="#_3-github-pages" aria-label="Permalink to &quot;3. GitHub Pages&quot;">​</a></h3><p>GitHub Pages 可以免费托管静态网站。</p><p><strong>启用方法：</strong></p><ol><li>进入仓库设置（Settings）</li><li>找到 <strong>Pages</strong> 选项</li><li>选择分支和目录</li><li>点击 <strong>Save</strong></li></ol><p><strong>访问地址</strong>：<code>https://用户名.github.io/仓库名</code></p><hr><h2 id="国内访问加速" tabindex="-1">国内访问加速 <a class="header-anchor" href="#国内访问加速" aria-label="Permalink to &quot;国内访问加速&quot;">​</a></h2><p>由于网络原因，国内访问 GitHub 可能较慢。以下是几种加速方案：</p><h3 id="方案一-使用加速器" tabindex="-1">方案一：使用加速器 <a class="header-anchor" href="#方案一-使用加速器" aria-label="Permalink to &quot;方案一：使用加速器&quot;">​</a></h3><h4 id="watt-toolkit-原-steam" tabindex="-1">Watt Toolkit（原 Steam++） <a class="header-anchor" href="#watt-toolkit-原-steam" aria-label="Permalink to &quot;Watt Toolkit（原 Steam++）&quot;">​</a></h4><p>Watt Toolkit 是一个免费的多功能工具箱，支持 GitHub 加速。</p><p><strong>下载地址</strong>：<a href="https://steampp.net" target="_blank" rel="noreferrer">https://steampp.net</a></p><p><strong>使用方法：</strong></p><ol><li>下载并安装 Watt Toolkit</li><li>打开软件，找到 <strong>网络加速</strong> 功能</li><li>勾选 <strong>GitHub</strong></li><li>点击 <strong>一键加速</strong></li></ol><p><strong>特点：</strong></p><ul><li>✅ 免费开源</li><li>✅ 支持 Windows/Mac/Linux</li><li>✅ 不仅加速 GitHub，还支持其他服务</li><li>✅ 无需注册账号</li></ul><h4 id="github520" tabindex="-1">GitHub520 <a class="header-anchor" href="#github520" aria-label="Permalink to &quot;GitHub520&quot;">​</a></h4><p>GitHub520 通过修改 hosts 文件加速访问。</p><p><strong>项目地址</strong>：<a href="https://github.com/521xueweihan/GitHub520" target="_blank" rel="noreferrer">https://github.com/521xueweihan/GitHub520</a></p><p><strong>使用方法：</strong></p><ol><li>访问项目页面</li><li>复制最新的 hosts 内容</li><li>粘贴到系统的 hosts 文件中</li></ol><p><strong>hosts 文件位置：</strong></p><ul><li>Windows：<code>C:\\Windows\\System32\\drivers\\etc\\hosts</code></li><li>Mac/Linux：<code>/etc/hosts</code></li></ul><h3 id="方案二-使用镜像站" tabindex="-1">方案二：使用镜像站 <a class="header-anchor" href="#方案二-使用镜像站" aria-label="Permalink to &quot;方案二：使用镜像站&quot;">​</a></h3><h4 id="fastgit" tabindex="-1">FastGit <a class="header-anchor" href="#fastgit" aria-label="Permalink to &quot;FastGit&quot;">​</a></h4><p><strong>地址</strong>：<a href="https://hub.fastgit.xyz" target="_blank" rel="noreferrer">https://hub.fastgit.xyz</a></p><p><strong>使用方法：</strong></p><ul><li>将 <code>github.com</code> 替换为 <code>hub.fastgit.xyz</code></li><li>例如：<code>https://hub.fastgit.xyz/用户名/仓库名</code></li></ul><h4 id="gitclone" tabindex="-1">GitClone <a class="header-anchor" href="#gitclone" aria-label="Permalink to &quot;GitClone&quot;">​</a></h4><p><strong>地址</strong>：<a href="https://gitclone.com" target="_blank" rel="noreferrer">https://gitclone.com</a></p><p><strong>使用方法：</strong></p><ul><li>在仓库地址前加上 <code>gitclone.com/</code></li><li>例如：<code>https://gitclone.com/github.com/用户名/仓库名</code></li></ul><h3 id="方案三-修改-git-配置" tabindex="-1">方案三：修改 Git 配置 <a class="header-anchor" href="#方案三-修改-git-配置" aria-label="Permalink to &quot;方案三：修改 Git 配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用国内镜像</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url.&quot;https://gitclone.com/github.com/&quot;.insteadOf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或者使用 FastGit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> url.&quot;https://hub.fastgit.xyz/&quot;.insteadOf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/&quot;</span></span></code></pre></div><hr><h2 id="推荐的-github-项目" tabindex="-1">推荐的 GitHub 项目 <a class="header-anchor" href="#推荐的-github-项目" aria-label="Permalink to &quot;推荐的 GitHub 项目&quot;">​</a></h2><h3 id="学习资源" tabindex="-1">学习资源 <a class="header-anchor" href="#学习资源" aria-label="Permalink to &quot;学习资源&quot;">​</a></h3><ul><li><a href="https://github.com/EbookFoundation/free-programming-books" target="_blank" rel="noreferrer">free-programming-books</a> - 免费编程书籍</li><li><a href="https://github.com/jwasham/coding-interview-university" target="_blank" rel="noreferrer">coding-interview-university</a> - 编程面试大学</li><li><a href="https://github.com/kamranahmedse/developer-roadmap" target="_blank" rel="noreferrer">developer-roadmap</a> - 开发者路线图</li></ul><h3 id="实用工具" tabindex="-1">实用工具 <a class="header-anchor" href="#实用工具" aria-label="Permalink to &quot;实用工具&quot;">​</a></h3><ul><li><a href="https://github.com/ohmyzsh/ohmyzsh" target="_blank" rel="noreferrer">Oh My Zsh</a> - 终端美化</li><li><a href="https://github.com/romkatv/powerlevel10k" target="_blank" rel="noreferrer">Powerlevel10k</a> - Zsh 主题</li><li><a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a> - Node.js 版本管理</li></ul><h3 id="项目模板" tabindex="-1">项目模板 <a class="header-anchor" href="#项目模板" aria-label="Permalink to &quot;项目模板&quot;">​</a></h3><ul><li><a href="https://github.com/vuejs/vitepress" target="_blank" rel="noreferrer">VitePress</a> - 静态网站生成器</li><li><a href="https://github.com/hexojs/hexo" target="_blank" rel="noreferrer">Hexo</a> - 博客框架</li><li><a href="https://github.com/vuejs/vue" target="_blank" rel="noreferrer">Vue</a> - 前端框架</li></ul><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="q-github-免费吗" tabindex="-1">Q: GitHub 免费吗？ <a class="header-anchor" href="#q-github-免费吗" aria-label="Permalink to &quot;Q: GitHub 免费吗？&quot;">​</a></h3><p>A: GitHub 对个人用户免费，包括无限的公开和私有仓库。</p><h3 id="q-如何删除仓库" tabindex="-1">Q: 如何删除仓库？ <a class="header-anchor" href="#q-如何删除仓库" aria-label="Permalink to &quot;Q: 如何删除仓库？&quot;">​</a></h3><p>A: 进入仓库设置（Settings）→ 滚动到底部 → 找到 <strong>Danger Zone</strong> → 点击 <strong>Delete this repository</strong></p><h3 id="q-如何找回密码" tabindex="-1">Q: 如何找回密码？ <a class="header-anchor" href="#q-如何找回密码" aria-label="Permalink to &quot;Q: 如何找回密码？&quot;">​</a></h3><p>A: 在登录页面点击 <strong>Forgot password</strong>，输入邮箱，按照邮件提示重置密码。</p><h3 id="q-github-有中文版吗" tabindex="-1">Q: GitHub 有中文版吗？ <a class="header-anchor" href="#q-github-有中文版吗" aria-label="Permalink to &quot;Q: GitHub 有中文版吗？&quot;">​</a></h3><p>A: GitHub 界面主要是英文，但可以通过浏览器翻译功能查看中文。</p><hr><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>GitHub 是开发者必备的工具，无论是学习、协作还是展示项目，都非常有用。希望这篇指南能帮助你快速上手 GitHub！</p><p><strong>记住：</strong></p><ul><li>🎯 多看优秀的开源项目</li><li>📝 养成写 README 的习惯</li><li>🤝 积极参与开源社区</li><li>🚀 用 GitHub Pages 展示自己</li></ul><hr><p><em>如果你有任何问题，欢迎在评论区留言！</em></p>`,92)])])}const d=a(l,[["render",n]]);export{u as __pageData,d as default};
